//package CodeForces;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class Cutting {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		int B=s.nextInt();
		int arr[]=new int[n];
		for(int i=0;i<n;i++)
		{
			arr[i]=s.nextInt();
		}

		int cut=0;
		int odd=0;
		int even=0;
		ArrayList<Integer> money=new ArrayList<Integer>();
		for(int i=0;i<n;i++)
		{
			if(arr[i]%2==0)
			{
				even++;
			}
			else
			{
				odd++;
			}

			if(even==odd&&even!=0&&i!=n-1)
			{
				money.add(Math.max(arr[i]-arr[i+1],arr[i+1]-arr[i]));
			}
		}

		money.sort(null);

		for(int x:money)
		{
			if(B>=x)
			{
				cut++;
				B=B-x;
			}
		}

		System.out.println(cut);

	}

}

